 46  /**
 47   * The conversation, for any application that has one.
 48   *
 49   * Two statuses get more than a badge. `WAITING_APPROVAL` is not an error and
 50   * not a hang: the run proposed a write, stopped at the policy gate, and is
 51   * waiting for a person — so the pane says so and points at the inbox.
 52   * `NEEDS_ATTENTION` is the honest end of a call that was dispatched but whose
 53   * outcome was never confirmed, and the worst thing the UI could do there is
 54   * invite a retry as if nothing had happened.
 55   */
 56  export default function AppConversationPane({
 57    threadId,
 58    turns,
 59    onTurnCompleted,
 60  }: {
 61    threadId: string;
 62    turns: WorkspaceQuery<ThreadTurn[]>;
 63    onTurnCompleted: () => void;
 64  }) {
 65    const { t, locale, formatDateTime } = useI18n();
 66    const { workspaceId, accessToken, permissions } = useFrontendSession();
 67    const cannotRun = permissions !== null && !permissions.includes("agent_run");
 68    const mutation = useWorkspaceMutation(`app-turns:${threadId}`);
 69    const submissionRef = useRef<TurnSubmissionState>(createSubmissionState());
 70    const [recoverySubmission, setRecoverySubmission] = useState<TurnSubmission | null>(null);
 71    const composerTextareaRef = useRef<HTMLTextAreaElement | null>(null);
 72    const [draft, setDraft] = useState("");
 73    // Auto-grow the composer textarea; reset when the draft clears.
 74    useEffect(() => {
 75      if (draft) return;
 76      const el = composerTextareaRef.current;
 77      if (el) el.style.height = "";
 78    }, [draft]);
 79    const [pendingInput, setPendingInput] = useState<string | null>(null);
 80    /** Live answer text from message.delta events, shown inside the pending bubble. */
 81    const [streamText, setStreamText] = useState<string | null>(null);
 82    const [streamRunId, setStreamRunId] = useState<string | null>(null);
 83    const streamAbortRef = useRef<AbortController | null>(null);
 84    const [stoppingRunId, setStoppingRunId] = useState<string | null>(null);
 85    const [cancelFeedback, setCancelFeedback] = useState<"requested" | "failed" | null>(null);
 86    const turnCount = turns.data?.length ?? 0;
 87    const { containerRef, onScroll, following, scrollToBottom } = useAutoScroll([
 88      streamText,
 89      turnCount,
 90    ]);
 91  
 92    // Another thread is another conversation: nothing in flight carries over.
 93    useEffect(() => {
 94      submissionRef.current = createSubmissionState();
 95      setRecoverySubmission(null);
 96      setDraft("");
 97      setPendingInput(null);
 98      setStreamText(null);
 99      setStreamRunId(null);
100      setStoppingRunId(null);
101      setCancelFeedback(null);
102      streamAbortRef.current = null;
103      return () => {
104        // Leave the backend run untouched, but stop this pane's stream so a
105        // response from the previous thread cannot update the next conversation.
106        streamAbortRef.current?.abort();
107        streamAbortRef.current = null;
108      };
109    }, [threadId]);
110  
111    const turnList = [...(turns.data ?? [])].sort((left, right) => left.sequence - right.sequence);
112    const hasActiveRun = turnList.some(
113      (turn) => PENDING_STATUSES.has(turn.status ?? "") && turn.agent_run_id,
114    );
115  
116    // A brand-new conversation should be typeable immediately: focus the
117    // composer once it has loaded with no turns.
118    useEffect(() => {
119      if (turns.loaded && turnList.length === 0) {
120        composerTextareaRef.current?.focus();
121      }
122    }, [turns.loaded, turnList.length]);
123  
124    // A reload loses the original SSE request. Poll durable active states so a
125    // waiting approval or cancellation also resolves without reopening the page.
126    useEffect(() => {
127      if (!hasActiveRun) return;
128      const interval = window.setInterval(() => {
129        if (!document.hidden) void turns.reload();
130      }, TURN_POLL_MS);
131      return () => window.clearInterval(interval);
132    }, [hasActiveRun, turns.reload]);
133  
134    // The optimistic copy stays up until the reloaded list actually contains
135    // the submitted turn (a just-submitted turn is always the list's last
136    // entry). Clearing before the reload lands makes the message blink out
137    // and back in for one reload round-trip.
138    const lastTurnInput = turnList.length > 0 ? turnList[turnList.length - 1].user_input : null;
139    const pendingVisible = pendingInput !== null && lastTurnInput !== pendingInput;
140    useEffect(() => {
141      if (pendingInput !== null && !mutation.pending && !pendingVisible) {
142        setPendingInput(null);
143        setStreamText(null);
144      }
145    }, [pendingInput, mutation.pending, pendingVisible]);
