148      event.preventDefault();
149      const text = draft.trim();
150      if (!text || mutation.pending || cannotRun) return;
151      setCancelFeedback(null);
152      const submission = submissionForInput(
153        submissionRef.current.draft,
154        text,
155        newSubmissionToken,
156      );
157      submissionRef.current = { ...submissionRef.current, draft: submission };
158      setPendingInput(text);
159      setStreamText("");
160      setStreamRunId(null);
161      const controller = new AbortController();
